import{_ as e,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"A Harbor-side Chat on CephFS - Patrick Donnelly, IBM","description":"","frontmatter":{"title":"A Harbor-side Chat on CephFS - Patrick Donnelly, IBM","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["CephFS","SEFS","Distributed Storage","Storage Cluster","High Availability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/A_Harbor-side_Chat_on_CephFS_-_Patrick_Donnelly_IBM.md","filePath":"posts/2025/A_Harbor-side_Chat_on_CephFS_-_Patrick_Donnelly_IBM.md","lastUpdated":1780459816000}'),l={name:"posts/2025/A_Harbor-side_Chat_on_CephFS_-_Patrick_Donnelly_IBM.md"};function n(s,a,i,h,g,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h3 id="cephfs-社区会议纪要-sefs-最新进展与讨论" tabindex="-1"><strong>CephFS 社区会议纪要：SEFS 最新进展与讨论</strong> <a class="header-anchor" href="#cephfs-社区会议纪要-sefs-最新进展与讨论" aria-label="Permalink to &quot;**CephFS 社区会议纪要：SEFS 最新进展与讨论**&quot;">​</a></h3><h4 id="会议概览" tabindex="-1"><strong>会议概览</strong> <a class="header-anchor" href="#会议概览" aria-label="Permalink to &quot;**会议概览**&quot;">​</a></h4><ul><li><strong>主持人</strong>：Patrick Donnelly（前 SEFS 团队负责人，自 2016 年起参与 Ceph 项目）</li><li><strong>主题</strong>：介绍 Tentacle 和 Umbrella 版本的 SEFS 新功能，并开放讨论社区问题。</li><li><strong>形式</strong>：技术分享 + 自由问答。</li></ul><h4 id="关键内容总结" tabindex="-1"><strong>关键内容总结</strong> <a class="header-anchor" href="#关键内容总结" aria-label="Permalink to &quot;**关键内容总结**&quot;">​</a></h4><h4 id="_1-tentacle-版本新功能" tabindex="-1"><strong>1. Tentacle 版本新功能</strong> <a class="header-anchor" href="#_1-tentacle-版本新功能" aria-label="Permalink to &quot;**1. Tentacle 版本新功能**&quot;">​</a></h4><ul><li><strong>Case Insensitive Subtree 支持</strong>：为目录树设置大小写不敏感，优化 Samba 在 SEFS 上的性能。</li><li><strong>File Block Diff API</strong>：对比文件快照间的数据块差异，优化备份效率。</li><li><strong>可观测性增强</strong>：包括 MDS Journal Replay 进度监控和数据 Scan 进度显示。</li><li><strong>灾难恢复优化</strong>：新增配置项禁用 Subvol 删除，记录 MDS Map 的创建时间。</li></ul><h4 id="_2-umbrella-版本新功能" tabindex="-1"><strong>2. Umbrella 版本新功能</strong> <a class="header-anchor" href="#_2-umbrella-版本新功能" aria-label="Permalink to &quot;**2. Umbrella 版本新功能**&quot;">​</a></h4><ul><li><strong>Per-Subvol Metrics</strong>：通过 Prometheus 或 Admin Socket 监控每个 Subvol 的 IO 指标。</li><li><strong>用户态 FScrypt 支持</strong>：兼容 Samba/NFS Ganesha，元数据和数据均加密。</li></ul><h4 id="开放讨论重点" tabindex="-1"><strong>开放讨论重点</strong> <a class="header-anchor" href="#开放讨论重点" aria-label="Permalink to &quot;**开放讨论重点**&quot;">​</a></h4><ul><li><strong>性能与运维问题</strong>：包括 SEFS Fuse 与 Kernel Driver 性能对比、Data Scan Cleanup 卡顿、MDS Journal Trimming 延迟等。</li><li><strong>架构与设计</strong>：讨论 MDS Cache/Journals/Metadata Pool 关系、快照备份负载隔离等。</li><li><strong>升级与灾难恢复</strong>：探讨 MDS 升级策略和文件系统布局修改。</li></ul><h4 id="行动计划" tabindex="-1"><strong>行动计划</strong> <a class="header-anchor" href="#行动计划" aria-label="Permalink to &quot;**行动计划**&quot;">​</a></h4><ul><li><strong>问题跟踪</strong>：提交 Data Scan Cleanup 卡顿问题至 Tracker，收集 SEFS Fuse vs Kernel 性能数据。</li><li><strong>功能优化</strong>：研究客户端 Cap 释放策略对 Journal Trimming 的影响，评估快照 MDS 隔离的可行性。</li><li><strong>文档补充</strong>：完善 MDS Cache/Journal 交互文档。</li></ul><h4 id="后续会议推荐" tabindex="-1"><strong>后续会议推荐</strong> <a class="header-anchor" href="#后续会议推荐" aria-label="Permalink to &quot;**后续会议推荐**&quot;">​</a></h4><ul><li><strong>SEFS 运维实战</strong>：Anthony Yetri 分享灾难恢复案例。</li><li><strong>Per-Subvol Metrics 深度解析</strong>：Egor/Eyore 演讲。</li></ul><h4 id="会议总结" tabindex="-1"><strong>会议总结</strong> <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;**会议总结**&quot;">​</a></h4><p>本次会议重点介绍了 CephFS 的最新进展，特别是 SEFS 的 Tentacle 和 Umbrella 版本的新功能。与会者就性能优化、架构设计、升级与灾难恢复等议题展开了深入讨论，并制定了后续行动计划。</p>',16)])])}const u=e(l,[["render",n]]);export{_ as __pageData,u as default};
